@Test
void hcpPairingConsumesOneUseLaunchTokenAndPinsDeviceIdentity() {
    var store = new MemoryHostStore();
    var permissions = new PermissionBroker(Clock.systemUTC());
    var tokens = new LocalTokenService(new SecureRandom(), Clock.systemUTC());
    var devices = new HostDeviceRegistry("host-1", tokens);
    try (var runtime = new AgentRuntimeBuilder().provider(new ScriptedModelProvider())
            .sessionRepository(store).permissionDecider(permissions).build();
         var sessions = new SessionApplicationService(runtime)) {
        var gateway = new HcpSessionGateway(new PromptApplicationService(sessions, store), null, devices, "host-1");
        String token = [REDACTED_CREDENTIAL]
        byte[] deviceKey = new byte[32];
        java.util.Arrays.fill(deviceKey, (byte) 7);
        Envelope paired = gateway.handle(Envelope.newBuilder().setConnectionId("pairing")
                .setPairingRequest(PairingRequest.newBuilder().setOperationId("install-1")
                        .setLaunchToken(token).setDeviceId("desktop-1")
                        .setDevicePublicKey(ByteString.copyFrom(deviceKey))).build()).getFirst();
        assertTrue(paired.hasPairingAck());
        assertEquals("host-1", paired.getPairingAck().getHostId());
        assertEquals("host-admin", paired.getPairingAck().getRole());
        assertTrue(paired.getPairingAck().getHostPublicKey().size() > 32);
        Envelope retry = gateway.handle(Envelope.newBuilder().setConnectionId("pairing")
                .setPairingRequest(PairingRequest.newBuilder().setOperationId("install-1")
                        .setLaunchToken("already-consumed").setDeviceId("desktop-1")
                        .setDevicePublicKey(ByteString.copyFrom(deviceKey))).build()).getFirst();
        assertTrue(retry.hasPairingAck());
        deviceKey[0] = 9;
        Envelope changed = gateway.handle(Envelope.newBuilder().setConnectionId("pairing")
                .setPairingRequest(PairingRequest.newBuilder().setOperationId("install-1")
                        .setLaunchToken("already-consumed").setDeviceId("desktop-1")
                        .setDevicePublicKey(ByteString.copyFrom(deviceKey))).build()).getFirst();
        assertEquals("permission.denied", changed.getError().getCode());
    }
}

